class Solution { public:
 vector<int> countVisitedNodes(vector<int>& edges){
  int n=edges.size();vector<int> deg(n),ans(n),order;for(int v:edges)++deg[v];
  queue<int> q;for(int i=0;i<n;++i)if(!deg[i])q.push(i);
  while(!q.empty()){int u=q.front();q.pop();order.push_back(u);int v=edges[u];if(--deg[v]==0)q.push(v);}
  for(int i=0;i<n;++i)if(deg[i] && !ans[i]){vector<int> cyc;int u=i;do{cyc.push_back(u);u=edges[u];}while(u!=i);
   for(int v:cyc)ans[v]=cyc.size();}
  for(int i=(int)order.size()-1;i>=0;--i){int u=order[i];ans[u]=ans[edges[u]]+1;}
  return ans;
 }
};
